import copy,json,sys,unittest
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from jinsedragon_base_fields import SOURCE,request,review,settled,bootstrap,mapping_hash
from round_fields import FieldError,derive
from ag_rolling_plan import validate_rolling_plan
from store import digest,Rejected
from unittest.mock import patch

H='<Header affiliate="0" ccyCode="" channel="I" freePlay="Y" gameCodeRGI="jinsedaodragon" gameID="20401" glsID="65535" lang="en_US" promotions="N" userID="null" userType="C" versionID="1_0" sessionID="{}"/>'
def payload(msg,session,first=False):return '<GameRequest type="'+msg+'">'+('<AccountData><CurrencyMultiplier>1</CurrencyMultiplier></AccountData>' if first else '')+H.format(session)+('<Stake total="100"/>' if first else '')+'</GameRequest>'
def text(msg,session,cash,body=''):
 a='<AccountData><AccountData><CurrencyMultiplier>1</CurrencyMultiplier></AccountData></AccountData>' if msg=='Logic' else '<AccountData/>'
 ready='Y' if msg=='Logic' else 'N'
 return f'<GameResponse type="{msg}"><Header gameID="20401" versionID="1_0" isRecovering="N" readyForEndGame="{ready}" sessionID="{session}"/>{a}<Balances><Balance name="CASH_BALANCE" value="{cash}"/></Balances>{body}</GameResponse>'
G='<GameResult stake="100" stakePerLine="100" paylineCount="1" totalWin="220" betID=""><ReelResults numSpins="1"><ReelSpin spinIndex="0" reelsetIndex="0" anywayWins="1" scatterWinCount="0" totalSpinWin="20" freeSpin="N" bonusAwarded="N"><ReelStops>1|2|3|4|5</ReelStops><AnywayWin winIndex="0" winVal="20" ways="1" awardIndex="0">25|26</AnywayWin></ReelSpin></ReelResults><BGInfo totalWagerWin="220" bgWinnings="220" baseGameSpinsRemaining="0" isMaxWin="0" expReelTriggerType="2" reelHeights="4"/><Orbs numJackpotWins="0"><Orb awardIndex="10" amount="400" position="0" winning="n" isJackpot="n"/><Orb awardIndex="12" amount="200" position="1" winning="y" isJackpot="n"/><Orb awardIndex="11" amount="300" position="2" winning="n" isJackpot="n"/><Orb awardIndex="9" amount="500" position="3" winning="n" isJackpot="n"/><Orb awardIndex="12" amount="200" position="4" winning="n" isJackpot="n"/><Orb awardIndex="8" amount="600" position="5" winning="n" isJackpot="n"/><Orb awardIndex="8" amount="600" position="6" winning="n" isJackpot="n"/><Orb awardIndex="8" amount="600" position="7" winning="n" isJackpot="n"/><Orb awardIndex="7" amount="800" position="8" winning="n" isJackpot="n"/></Orbs></GameResult>'
def step(msg,q,p,cash):return dict(msgId=msg,requestPayload=q,responsePayload=p,responseXml=p,responseBalance=cash,elapsedMs=0)
def raw():return dict(sourceKey=SOURCE,protocol='wms',fixtureOnly=False,roundFieldsVersion='sg-round-fields-v1',startBalanceRaw=1000,steps=[step('Logic',payload('Logic','first',True),text('Logic','paid',1120,G),1120),step('EndGame',payload('EndGame','paid'),text('EndGame','end',1120),1120)])

class JinseDragonBaseTests(unittest.TestCase):
 def test_complete_independent_derivation_and_exact_plan(self):
  r=raw();self.assertEqual(review(r)['next'],None);f=settled(r,mapping_hash());self.assertEqual(f,derive(r));self.assertEqual((f['bet'],f['mul'],f['bonus']),(1,220/100,0))
  reg=json.loads((Path(__file__).resolve().parents[2]/'config/ag-rolling-plans.json').read_text());p=reg['plans']['32779'];self.assertEqual(validate_rolling_plan(p),p)
  for k,v in [('betRaw',101),('maxSteps',3),('wmsGameId',20442),('runtimeGameId',20401)]:
   with self.assertRaises(Rejected):validate_rolling_plan({**p,k:v})
 def test_money_cumulative_and_anyway_sum_are_all_required(self):
  for a,b in [('winVal="20"', 'winVal="21"'), ('bgWinnings="220"', 'bgWinnings="221"'), ('totalSpinWin="20"', 'totalSpinWin="21"')]:
   r=raw();s=r['steps'][0];s['responsePayload']=s['responseXml']=s['responseXml'].replace(a,b)
   with self.assertRaises(FieldError):review(r)
  r=raw();r['steps'][0]['responseBalance']+=1
  with self.assertRaises(FieldError):review(r)
 def test_partial_early_end_and_session_rotation_rejected(self):
  r=raw()
  with self.assertRaises(FieldError):settled({**r,'steps':r['steps'][:1]},mapping_hash())
  with self.assertRaises(FieldError):review({**r,'steps':[r['steps'][1]]})
  with self.assertRaises(FieldError):review({**r,'steps':r['steps']+[r['steps'][1]]})
  altered=copy.deepcopy(r);altered['steps'][1]['responsePayload']=altered['steps'][1]['responseXml']=altered['steps'][1]['responseXml'].replace('<AccountData/>','<AccountData><CurrencyMultiplier>1</CurrencyMultiplier></AccountData>')
  with self.assertRaises(FieldError):review(altered)
  r['steps'][1]['requestPayload']=payload('EndGame','wrong')
  with self.assertRaises(FieldError):review(r)
 def test_unknown_quickhits_positions_and_feature_and_nodes_fail_closed(self):
  for a,b in [('freeSpin="N"', 'freeSpin="Y"'), ('bonusAwarded="N"', 'bonusAwarded="Y"'), ('anywayWins="1"', 'anywayWins="2"'), ('scatterWinCount="0"', 'scatterWinCount="1"'), ('stake="100"', 'stake="101"'), ('stakePerLine="100"', 'stakePerLine="101"'), ('paylineCount="1"', 'paylineCount="2"'), ('isMaxWin="0"', 'isMaxWin="1"'), ('baseGameSpinsRemaining="0"', 'baseGameSpinsRemaining="1"'), ('winVal="20"', 'winVal="21"'), ('awardIndex="0"', 'awardIndex="99999"'), ('ways="1"', 'ways="99999"'), ('winIndex="0"', 'winIndex="1"'), ('>25|26</AnywayWin>', '>0|1|40</AnywayWin>'), ('totalSpinWin="20"', 'totalSpinWin="21"'), ('totalWin="220"', 'totalWin="221"'), ('<BGInfo', '<UnknownFeature/><BGInfo'), ('</GameResult>', '<WheelInfo featureType="FreeSpins" wheelStop="2"/></GameResult>'), ('reelsetIndex="0"', 'reelsetIndex="1"'), ('spinIndex="0"', 'spinIndex="1"'), ('<CurrencyMultiplier>1</CurrencyMultiplier>', '<CurrencyMultiplier>2</CurrencyMultiplier>'), ('readyForEndGame="Y"', 'readyForEndGame="N"'), ('<BGInfo', 'unexpected<BGInfo'), ('expReelTriggerType="2"', 'expReelTriggerType="99"'), ('reelHeights="4"', 'reelHeights="99"'), ('numJackpotWins="0"', 'numJackpotWins="1"'), ('winning="y"', 'winning="n"'), ('position="0"', 'position="99"'), ('<BGInfo', '<BGInfo isBigBet="0"')]:
   r=raw();r['steps'][0]['responsePayload']=r['steps'][0]['responseXml']=r['steps'][0]['responseXml'].replace(a,b)
   with self.assertRaises(FieldError):review(r)
  with self.assertRaises(FieldError):request(payload('Logic','first',True).replace('total="100"','total="101"'),'Logic',True)
 def test_init_capability_is_not_paid_or_feature_admission(self):
  q=payload('Init','first');p=text('Init','rotated',1000,'<GameInfo><Stakes>100|200|</Stakes><PageInfo pageCount="1"/></GameInfo>');s=step('Init',q,p,1000)
  self.assertEqual(bootstrap(s,'first'),dict(validated=True,session='rotated',balanceRaw=1000))
  for a,b in [('100|200|','99|200|'),('pageCount="1"','pageCount="2"'),('isRecovering="N"','isRecovering="Y"'),('</GameResponse>','<GameResult/></GameResponse>')]:
   t=copy.deepcopy(s);t['responsePayload']=t['responseXml']=p.replace(a,b)
   with self.assertRaises(FieldError):bootstrap(t,'first')
 def test_missing_or_tampered_wiring_proof_never_admits_plan(self):
  path=Path(__file__).resolve().parents[2]/'config/ag-rolling-plans.json';reg=json.loads(path.read_text());p=reg['plans']['32779'];original=Path.read_text
  for kind in ('missing','hash','count','not_verified','records','raws','credit','rejected','source_constructor','sample_count','type_credit','policy'):
   bad=copy.deepcopy(reg);proof=bad['proofs']['32779']
   if kind=='missing':proof.pop('wiringEvidence')
   elif kind=='hash':proof['wiringEvidence']['evidenceHash']='a'*64
   elif kind=='records':
    proof['wiringEvidence']['fullRecordsHash']='a'*64
   elif kind=='raws':proof['acceptedRawHashes'][0]='a'*64
   elif kind=='credit':proof['wiringEvidence']['failedOrHistoricalRoundsCredited']=1
   elif kind=='rejected':proof['rejectedHistoricalPrefixes'].append({'index':0,'rawHash':'a'*64})
   elif kind=='source_constructor':proof['wiringEvidence']['ownSourcePayloadSemanticHash']='a'*64
   elif kind=='sample_count':proof['sampledRounds']=999
   elif kind=='type_credit':proof['wiringEvidence']['acceptedFreeRounds']=1
   elif kind=='policy':proof['wiringEvidence']['ordinaryContractHash']='a'*64
   else:
    proof['wiringEvidence']['sourceRoutesValidated' if kind=='count' else 'actualRecordAndVerifyIpc']=1999 if kind=='count' else False
    value=proof['wiringEvidence'];value['evidenceHash']=digest({k:v for k,v in value.items() if k!='evidenceHash'})
   if kind not in ('missing','hash'):
    value=proof['wiringEvidence'];value['evidenceHash']=digest({k:v for k,v in value.items() if k!='evidenceHash'})
   def read(current,*args,**kwargs):return json.dumps(bad) if current==path else original(current,*args,**kwargs)
   with self.subTest(kind=kind),patch.object(Path,'read_text',read):
    with self.assertRaises(Rejected):validate_rolling_plan(p)
